param(
  [switch]$SkipConversion
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$projectRoot = (Get-Location).Path

if (-not (Test-Path -LiteralPath (Join-Path $projectRoot "package.json"))) {
  throw "package.json was not found. Run this script from the project root."
}

$targetRoot = Join-Path $projectRoot "data-source\product-center\pumps\plunger-pump\ea"
New-Item -ItemType Directory -Force -Path $targetRoot | Out-Null

$detailPath = Join-Path $targetRoot "01_EA常规柱塞泵_详情页资料_zh.xlsx"
$specPath = Join-Path $targetRoot "02_EA常规柱塞泵_规格参数_zh.xlsx"

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Backup-IfExists {
  param([string]$Path)

  if (Test-Path -LiteralPath $Path) {
    $backupPath = "$Path.corrupt-$timestamp.bak"
    Copy-Item -LiteralPath $Path -Destination $backupPath -Force
    Write-Host "Backup created: $backupPath" -ForegroundColor Yellow
  }
}

function Write-Base64File {
  param(
    [string]$Path,
    [string]$Base64
  )

  $bytes = [System.Convert]::FromBase64String($Base64)
  [System.IO.File]::WriteAllBytes($Path, $bytes)
}

function Get-Sha256 {
  param([string]$Path)

  $stream = [System.IO.File]::OpenRead($Path)

  try {
    $sha = [System.Security.Cryptography.SHA256]::Create()

    try {
      $hash = $sha.ComputeHash($stream)
      return ([System.BitConverter]::ToString($hash)).Replace("-", "")
    }
    finally {
      $sha.Dispose()
    }
  }
  finally {
    $stream.Dispose()
  }
}

function Test-Xlsx {
  param(
    [string]$Path,
    [string]$ExpectedSha256
  )

  $bytes = [System.IO.File]::ReadAllBytes($Path)

  if ($bytes.Length -lt 4) {
    throw "File is too small: $Path"
  }

  $header = [System.BitConverter]::ToString($bytes[0..3])

  if ($header -ne "50-4B-03-04") {
    throw "Invalid XLSX header: $header | $Path"
  }

  Add-Type -AssemblyName System.IO.Compression
  Add-Type -AssemblyName System.IO.Compression.FileSystem

  $stream = $null
  $archive = $null

  try {
    $stream = [System.IO.File]::Open(
      $Path,
      [System.IO.FileMode]::Open,
      [System.IO.FileAccess]::Read,
      [System.IO.FileShare]::Read
    )

    $archive = New-Object System.IO.Compression.ZipArchive(
      $stream,
      [System.IO.Compression.ZipArchiveMode]::Read,
      $false
    )

    if ($archive.Entries.Count -lt 5) {
      throw "XLSX ZIP contains too few entries: $Path"
    }
  }
  finally {
    if ($null -ne $archive) {
      $archive.Dispose()
    }

    if ($null -ne $stream) {
      $stream.Dispose()
    }
  }

  $actualSha256 = Get-Sha256 -Path $Path

  if ($actualSha256 -ne $ExpectedSha256) {
    throw "SHA-256 mismatch for $Path`nExpected: $ExpectedSha256`nActual:   $actualSha256"
  }

  Write-Host "Valid XLSX: $Path" -ForegroundColor Green
  Write-Host "  Header : $header"
  Write-Host "  Size   : $($bytes.Length) bytes"
  Write-Host "  SHA256 : $actualSha256"
}

$detailBase64 = @'

'@

$specBase64 = @'

'@

Backup-IfExists -Path $detailPath
Backup-IfExists -Path $specPath

Write-Host ""
Write-Host "Writing clean EA Excel workbooks..." -ForegroundColor Cyan

Write-Base64File -Path $detailPath -Base64 $detailBase64
Write-Base64File -Path $specPath -Base64 $specBase64

Write-Host ""
Test-Xlsx -Path $detailPath -ExpectedSha256 "A4404A0B6EAAA70F8D9C65AF25BD2BB8B43DE2B89D9755BFACA44902486CA0B6"
Test-Xlsx -Path $specPath -ExpectedSha256 "C13AED39C24D06668881A413A4751156CA40822506D7B5B49E6775A11D6945AB"

Write-Host ""
Write-Host "Both EA source workbooks were restored successfully." -ForegroundColor Green

if ($SkipConversion) {
  Write-Host "Conversion was skipped." -ForegroundColor Yellow
  exit 0
}

$v3Path = Join-Path $projectRoot "generate_ea_product_detail_data_v3_excel_com_utf8bom.ps1"

if (-not (Test-Path -LiteralPath $v3Path)) {
  Write-Host ""
  Write-Host "V3 conversion script was not found:" -ForegroundColor Yellow
  Write-Host $v3Path
  Write-Host ""
  Write-Host "The Excel files are already repaired. Run V3 manually after placing it in the project root." -ForegroundColor Yellow
  exit 0
}

Write-Host ""
Write-Host "Starting V3 conversion..." -ForegroundColor Cyan

& powershell -ExecutionPolicy Bypass -File $v3Path

if ($LASTEXITCODE -ne 0) {
  throw "Excel files were restored, but V3 conversion failed."
}

Write-Host ""
Write-Host "EA Excel restore and conversion completed." -ForegroundColor Green
